'use strict';
const fs=require('node:fs'),assert=require('node:assert/strict'),{chromium,webkit}=require('playwright');
const dir='.github/fixtures/fgts-dashboard',out='qa/fgts-dashboard';fs.mkdirSync(out,{recursive:true});
const html=fs.readFileSync(dir+'/fixture.html','utf8').replace('<script src="fixture-runtime.js"></script>','<script>'+fs.readFileSync(dir+'/fixture-runtime.js','utf8')+'</script>');
(async()=>{const results=[];for(const [engine,type] of [['chromium',chromium],['webkit',webkit]]){const browser=await type.launch();try{for(const width of [320,393,1366]){const ctx=await browser.newContext({viewport:{width,height:980},locale:'pt-BR',serviceWorkers:'block'});const page=await ctx.newPage(),errors=[],network=[];page.on('pageerror',e=>errors.push(String(e)));await page.route('**/*',r=>{network.push(r.request().url());return r.abort()});try{await page.setContent(html);await page.getByRole('button',{name:'Executar regressão'}).click();const proof=await page.locator('#proof').innerText();assert.match(proof,/^PASS 61 DOM assertions/);assert.deepEqual(errors,[]);assert.deepEqual(network,[]);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'page overflow');await page.screenshot({path:out+'/'+engine+'-'+width+'.png',fullPage:true});results.push({engine,width,pass:true,assertions:61,synthetic_only:true,production_network:false});}finally{await ctx.close()}}}finally{await browser.close()}}fs.writeFileSync(out+'/results.json',JSON.stringify({pass:true,results,limitations:['Focused DOM fixture with actual candidate dashboard renderer and synthetic dependencies/CSS; not full application or physical-device acceptance.']},null,2));console.log(JSON.stringify({pass:true,cases:results.length}));})().catch(e=>{console.error(e);process.exitCode=1});
